package dev.slipstream;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import org.joml.Vector3d;
import static dev.slipstream.TransitGraph.*;
/** Scheduler and resource lifecycle proof; these are not real multiplayer acceptance. */
public final class TrafficTests {
 static final UUID OWNER=UUID.randomUUID();static final Cell X=new Cell(1,0,0);
 static List<Node> line(int x,int z,int count){var path=new ArrayList<Node>();for(int i=0;i<count;i++)path.add(new Node(new Cell(x+i,82,z),i==0?"ST_Harbour":i==count-1?"ST_Overlook":"ST_Straight",0,OWNER,i==0?List.of(X):i==count-1?List.of(X.opposite()):List.of(X.opposite(),X)));return path;}
 static void check(boolean value,String why){if(!value)throw new AssertionError(why);}
 public static void main(String[] args){
  var path=line(-40,0,512);var graph=new TransitGraph();path.forEach(graph::add);check(graph.route(path.getFirst().cell(),OWNER).size()==512,"512 part route crosses 17 columns");check(RouteChunks.sections(path).size()<=TransitLimits.ROUTE_SECTIONS,"bounded512 corridor");check(RouteChunks.sections(path).stream().anyMatch(k->k.x()<0),"negative coordinate chunk floor division");
  check(graph.stations().size()==2,"cached station index");var cached=graph.stations();graph.nodes.remove(path.getLast().cell());graph.nodes.put(path.getLast().cell(),path.getLast());check(graph.stations().size()==2&&graph.stations()!=cached,"station cache refreshes after same-size edits");var restored=TransitGraph.restore(graph.snapshot());check(restored.snapshot().equals(graph.snapshot()),"long snapshot exact roundtrip");graph.add(new Node(new Cell(472,82,0),"ST_Straight",0,OWNER,List.of(X.opposite(),X)));graph.nodes.remove(path.getLast().cell());graph.add(new Node(path.getLast().cell(),"ST_Straight",0,OWNER,List.of(X.opposite(),X)));graph.add(new Node(new Cell(473,82,0),"ST_Overlook",0,OWNER,List.of(X.opposite())));check(graph.destinations(path.getFirst().cell(),OWNER).isEmpty(),"journey cap remains bounded");
  UUID a=UUID.randomUUID(),b=UUID.randomUUID(),c=UUID.randomUUID();var traffic=new Traffic();check(traffic.reserve(a,path),"first admission");check(traffic.reserve(b,line(0,10,100)),"independent networks simultaneous");check(traffic.reserve(c,path),"shared same-direction convoy");var reverse=new ArrayList<>(path);Collections.reverse(reverse);check(!traffic.reserve(UUID.randomUUID(),reverse),"opposing route waits");
  List<Node> fork=new ArrayList<>(path);var junction=fork.get(20);fork.set(20,new Node(junction.cell(),"ST_Splitter",0,OWNER,List.of(X.opposite(),X,new Cell(0,0,1))));fork.set(21,new Node(junction.cell().add(new Cell(0,0,1),1),"ST_Overlook",0,OWNER,List.of(new Cell(0,0,-1))));fork=fork.subList(0,22);check(Traffic.conflicts(path,fork),"conflicting junction exit waits");
  check(traffic.claimLanding(a,path.getLast().cell()),"landing acquired");check(!traffic.claimLanding(b,path.getLast().cell()),"landing exclusion");traffic.release(c);check(traffic.reservations.containsKey(a)&&traffic.reservations.containsKey(b),"one abort retains peers");check(!traffic.landingFree(b,path.getLast().cell()),"peer abort cannot free landing");traffic.release(a);check(traffic.claimLanding(b,path.getLast().cell()),"owner cleanup frees landing");
  var lead=new Ride(null,null,path,Ride.feet(path.getFirst()));var follow=new Ride(null,null,path,Ride.feet(path.getFirst()));lead.sequence=1;follow.sequence=2;lead.progress=20;follow.progress=10;check(Math.abs(follow.limitBehind(lead)-16)<.00001,"four block headway");check(lead.limitBehind(follow)==lead.total,"leader does not follow follower");lead.progress=9;check(follow.limitBehind(lead)==follow.progress,"overshoot still holds behind earlier rider");lead.progress=20;check(lead.timeout()>280,"distance-based timeout supports long trip");
  for(double distance=0;distance<lead.total;distance+=.11){lead.progress=distance;check(Math.abs(lead.nearest(lead.at(distance))-distance)<.001,"indexed projection preserves long guided route");check(Double.isFinite(lead.direction(distance).length()),"direction finite");}
  AtomicInteger retains=new AtomicInteger(),releases=new AtomicInteger();Map<Integer,CompletableFuture<Integer>> futures=new HashMap<>();var loads=new ScopedLoads<Integer,Integer>(3,k->futures.computeIfAbsent(k,n->new CompletableFuture<>()),k->retains.incrementAndGet(),k->releases.incrementAndGet());
  var one=loads.request(Set.of(1,2));var two=loads.request(Set.of(2,3));check(loads.request(Set.of(4))==null,"global budget");loads.tick();futures.get(1).complete(1);futures.get(2).complete(2);loads.tick();futures.get(3).complete(3);loads.tick();check(one.ready()&&two.ready(),"all chunks ready");check(retains.get()==3,"shared retention once per section");one.close();one.close();check(releases.get()==1&&two.ready(),"idempotent per-rider cleanup retains shared chunks");two.close();check(releases.get()==3&&loads.entries.isEmpty(),"last rider releases own holds");
  var late=loads.request(Set.of(8));loads.tick();late.close();futures.get(8).complete(8);loads.tick();check(retains.get()==3,"late load after cancel never retained");var broken=loads.request(Set.of(9));loads.tick();futures.get(9).completeExceptionally(new IllegalStateException("native failure"));loads.tick();check(broken.failed(),"load failure propagated");broken.close();var end=loads.request(Set.of(10));loads.tick();futures.get(10).complete(10);loads.tick();loads.close();end.close();check(retains.get()==releases.get(),"shutdown balances all holds");
  System.out.println("Traffic/long-route checks passed: separate/shared/opposed/junction/landing, own cancellation, indexed512 path, chunk budget/refcounts/failure/late completion/shutdown. Real multiplayer pending.");
 }
}
